import{z as s,x as n,o as e,c as p,q as t,j as E,D as l,d as A,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"MoE 训练 all-to-all","description":"","frontmatter":{"title":"MoE 训练 all-to-all","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/moe-training-all2all.md","filePath":"llm/moe-training-all2all.md","lastUpdated":1791063341000}'),d={name:"llm/moe-training-all2all.md"};function m(B,a,c,h,_,u){const o=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="moe-训练-all-to-all" tabindex="-1">MoE 训练 all-to-all <a class="header-anchor" href="#moe-训练-all-to-all" aria-label="Permalink to &quot;MoE 训练 all-to-all&quot;">​</a></h1><div class="epigraph"><p>专家住在不同卡上时，每个微批都要把 token 按路由结果置换过去再置换回来；这两次 All-to-All 是稀疏计算换来的税，日历必须把它们算进去。</p><footer>—— Lepikhin et al., GShard；Fedus et al., Switch Transformers</footer></div><p><a href="/llm/grad-accum-microbatch">上一课</a>表明，降微批、加累积会增加集合通信次数。稠密 TP 的 All-Reduce 已经贵；<a href="/llm/moe-routing">MoE 路由</a> 之后，专家并行还要在每个微批、每个 MoE 层做 dispatch 与 combine 两次 All-to-All。本课不重讲 top-\\(k\\) 怎么打分。缺口是训练时这条置换通信如何与 1F1B / 重叠 / 累积共存，以及容量、落后者如何把税变成墙。异步检查点从下一课开始转向故障，本课先把稳态通信税付清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GShard 与 Switch 把专家分到设备上，token 跟着专家走。体积 \\(\\propto b_{\\mathrm{micro}}\\times s\\times d\\times k\\)（再加容量空洞）。Ulysses 的 All-to-All 键是序列块；MoE 的键是专家 id，两者叠在同一模型里时，同一层可能连续打两种置换，网络队列更容易堵。1F1B 的阶段若把 MoE 层放在边界，阶段间激活发送与专家置换抢链路。</p><p>路由抖动会让每次微批的通信形状微变；实现常用固定容量 padding，把抖动变成空洞字节。空洞不参与有效 FLOPs，但参与带宽，MFU 看起来差。这是专家粒度课的通信-计算比在训练日历上的落地。<span class="marginnote">「容量空洞」翻译成大白话：为了收发定长的数据块，系统给每个专家预留了固定大小的「集装箱位」。负载不均时，有的集装箱塞满了，有的只装了三成——但空格子照样要占用带宽运输。这些空格子就是空洞：不产生任何有用的计算，却真实消耗网络时间。</span></p><h3 id="累积把税乘开" tabindex="-1">累积把税乘开 <a class="header-anchor" href="#累积把税乘开" aria-label="Permalink to &quot;累积把税乘开&quot;">​</a></h3><p>每个微批独立路由、独立 All-to-All。\\(k_{\\mathrm{acc}}\\) 增大，优化器虽稀，网络次数线性涨。MoE 上「用累积换显存」可能让通信成为主词，应优先重计算、优先更大 \\(b_{\\mathrm{micro}}\\)、优先更少的 MoE 层跨节点。</p>',8)),(e(),E(r,null,{default:l(()=>[i(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%A2%AF%E5%BA%A6%E7%B4%AF%E7%A7%AF%20k_acc%20%E4%B8%AA%E5%BE%AE%E6%89%B9%22%5D%20--%3E%20M1%5B%22%E5%BE%AE%E6%89%B9%201%EF%BC%9A%E8%B7%AF%E7%94%B1%20%2B%20%E4%B8%A4%E6%AC%A1%20A2A%22%5D%0A%20%20G%20--%3E%20M2%5B%22%E5%BE%AE%E6%89%B9%202%EF%BC%9A%E8%B7%AF%E7%94%B1%20%2B%20%E4%B8%A4%E6%AC%A1%20A2A%22%5D%0A%20%20G%20--%3E%20M3%5B%22%E2%80%A6%E2%80%A6%E5%BE%AE%E6%89%B9%20k_acc%22%5D%0A%20%20M1%20--%3E%20TOT%5B%22A2A%20%E6%80%BB%E6%AC%A1%E6%95%B0%20%3D%202%20x%20%E5%B1%82%E6%95%B0%20x%20k_acc%22%5D%0A%20%20M2%20--%3E%20TOT%0A%20%20M3%20--%3E%20TOT%0A%20%20TOT%20--%3E%20W%7B%22A2A%20%E5%8D%A0%E5%A2%99%E9%92%9F%E6%AF%94%E4%BE%8B%22%7D%0A%20%20W%20--%20%22%E8%BF%87%E9%AB%98%22%20--%3E%20FIX%5B%22%E6%94%B9%E7%94%A8%E9%87%8D%E8%AE%A1%E7%AE%97%20%2F%20%E6%9B%B4%E5%A4%A7%20microbatch%20%2F%20%E5%87%8F%20EP%20%E8%B7%A8%E5%BA%A6%22%5D%0A%20%20W%20--%20%22%E5%8F%AF%E6%8E%A5%E5%8F%97%22%20--%3E%20OK%5B%22%E7%BB%B4%E6%8C%81%E9%85%8D%E7%BD%AE%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">All-to-All 不是 All-Reduce。实现错成规约会把不同专家的输入加在一起。对拍应用专家输出范数，而不只对总损失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 EP 组放在 NVLink 域，跨节点只走 DP 或 PP。<span class="marginnote">直觉类比：把专家放进 NVLink 域，就像把经常互相递文件的同事安排坐同一张办公桌——每次 dispatch/combine 都是来回递纸条，同一张桌子的传递快得多；跨节点相当于跨楼层跑腿，速度差一个量级。专家间的 token 每层每批都要递两次，所以「坐哪儿」直接决定这间公司的办事速度。</span>Tutel、DeepSpeed-MoE、Megatron-MoE 一类实现提供分组 All-to-All 与容量掩码。调度上：先算路由（本地、便宜），post dispatch，用无关计算重叠，wait 后跑专家 GEMM，再 post combine。与 DualPipe 双流叠加时，两套微批的 All-to-All 必须分缓冲，避免专家 batch 混洗。</p><p>负载均衡（辅助损失或无辅助偏置）是为了让各专家 token 数接近容量，从而让 All-to-All 体积可预测。失衡时热专家所在卡变成计算落后者，下一课的 straggler 会先打在这里。</p><h3 id="与-pp、sp-的切分" tabindex="-1">与 PP、SP 的切分 <a class="header-anchor" href="#与-pp、sp-的切分" aria-label="Permalink to &quot;与 PP、SP 的切分&quot;">​</a></h3><p>MoE 层尽量完整放在一个流水阶段内，不要把 dispatch 与专家计算分到两段。Ulysses 的序列分片要在路由之前定义「token 属于哪张 SP 卡」；通常先 SP 再 EP，或采用框架已经验证的一种顺序，禁止实验里私自交换而不对拍。</p><p><span class="marginnote">Dropless MoE 取消容量丢弃，All-to-All 体积随负载上漂，日历更难重叠。需要动态形状或预留上限。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稀疏 FFN 把 FLOPs 降到 \\(k\\) 个专家，但把规约通信换成不规则置换。训练步的墙上时间变成 \\(\\max(\\text{稠密注意力},\\text{专家 GEMM},\\text{两次 A2A})\\) 的组合。\\(k\\)、容量因子、\\(b_{\\mathrm{micro}}\\) 同时进入这个 max。路由崩溃时计算项变小、通信项因空洞仍在，比值恶化。</p>',9)),(e(),E(r,null,{default:l(()=>[i(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%9C%AC%E5%9C%B0%E8%B7%AF%E7%94%B1%22%5D%20--%3E%20D%5B%22Dispatch%20All-to-All%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%B8%93%E5%AE%B6%20GEMM%22%5D%0A%20%20E%20--%3E%20C%5B%22Combine%20All-to-All%22%5D%0A%20%20C%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解决卡死与掉卡：A2A 是同步障碍，一卡挂则组挂。那是弹性与故障率课。也不解决检查点里专家分片如何按不同 EP 度恢复——那是两课后的格式课。稳态下若 A2A 已经占总时间一半，应减 EP 跨度或减 MoE 层数，而不是再加梯度累积。<span class="marginnote">常见误区：以为某一卡慢只拖慢它自己。All-to-All 是集体通信——所有参与卡必须在同一关口互相等齐，最慢的那张卡决定所有人过关的时间，这就是「落后者税」。它和「加均衡损失」直接相关：热专家所在的卡算得多、收得多，往往就是那个最慢的人。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲路由公式；只补训练日历上的两次置换税。</li><li>累积与双流会乘开 All-to-All 次数；EP 组应留在高带宽域。</li><li>容量空洞占带宽；负载均衡也是网络平滑。</li><li>与 Ulysses 的 A2A 键不同，顺序要对拍。</li><li>出处：Lepikhin et al., GShard, 2020；Fedus et al., Switch, 2021；Hwang et al., Tutel。</li></ul>',4))])}const D=s(d,[["render",m]]);export{T as __pageData,D as default};
